{"source":"def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    present = set()
    high = 0
    open_transaction = False
    saved_present = set()
    saved_high = 0
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            present.add(ident)
            if ident > high:
                high = ident
        elif op == 'delete':
            ident = action.get('id')
            if ident in present:
                present.remove(ident)
        elif op == 'begin':
            open_transaction = True
            saved_present = present.copy()
            saved_high = high
        elif op == 'commit':
            open_transaction = False
        elif op == 'rollback':
            open_transaction = False
            present = saved_present.copy()
            high = saved_high
    return high + 1
